function CountOpeningBrackets(brackets: string): int
    reads brackets
    ensures 0 <= result <= |brackets|
{
    var count := 0;
    var i := 0;
    while (i < |brackets|)
        invariant 0 <= count <= i
        invariant count == CountOpeningBrackets(brackets[..i])
    {
        if (brackets[i] == '<') {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function CountClosingBrackets(brackets: string): int
    reads brackets
    ensures 0 <= result <= |brackets|
{
    var count := 0;
    var i := 0;
    while (i < |brackets|)
        invariant 0 <= count <= i
        invariant count == CountClosingBrackets(brackets[..i])
    {
        if (brackets[i] == '>') {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function AllOpeningBracketsBalanced(brackets: string): bool
    reads brackets
    ensures result == true || result == false
{
    var balance := 0;
    var i := 0;
    while (i < |brackets|)
        invariant -1 <= balance <= i
    {
        if (brackets[i] == '<') {
            balance := balance + 1;
        } else if (brackets[i] == '>') {
            balance := balance - 1;
        }
        if (balance < 0) {
            return false;
        }
        i := i + 1;
    }
    return balance == 0;
}
